import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace, DoubleSide } = ctx.THREE;

  const root = new Group();
  const inner = new Group();
  root.add(inner);

  // Atlas region: 0, 0, 512, 320 — aspect 1.6:1
  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;
  const planeHeight = 0.6;
  const planeWidth = planeHeight * aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
    opacity: 0,
  });

  const mesh = new Mesh(geometry, material);
  inner.add(mesh);

  // Load accent texture and apply to material map
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = SRGBColorSpace;
      tex.minFilter = ctx.THREE.LinearFilter;
      tex.magFilter = ctx.THREE.LinearFilter;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Billboard: orient plane toward camera each frame
  mesh.onBeforeRender = (_renderer, _scene, camera) => {
    mesh.lookAt(camera.position);
  };

  // Entrance: rise-in (y -0.4 -> 0, power3.out, 0.7s)
  // + fade-up (opacity 0 -> 1, power2.out, 0.5s)
  // + weighted-settle (scale 0.96 -> 1.0, power4.out, 0.9s)
  const entranceTl = gsap.timeline();
  entranceTl.fromTo(
    inner.position,
    { y: -0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  entranceTl.fromTo(
    material,
    { opacity: 0 },
    { opacity: 1, duration: 0.5, ease: 'power2.out' },
    0
  );
  entranceTl.fromTo(
    inner.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );

  // Idle: gentle floating breath (<=2% displacement, slow)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.2 });
  idleTl.to(inner.position, {
    y: 0.08,
    duration: 3,
    ease: 'power1.inOut',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    entranceTl.kill();
    idleTl.kill();
    if (loadedTexture) loadedTexture.dispose();
    geometry.dispose();
    material.dispose();
  };

  return root;
}
